import { useEffect, useState } from 'react';
import {
  JxToggle,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
  JxBadge,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';

interface AppearanceSettings {
  theme: Theme;
  scale: number;
  compact: boolean;
  fontFamily: string;
}

interface AppearanceScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

const themeLabels: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceScreen({ onChange }: AppearanceScreenProps) {
  const [theme, setTheme] = useState<Theme>('system');
  const [scale, setScale] = useState(100);
  const [compact, setCompact] = useState(false);
  const [fontFamily, setFontFamily] = useState('sans');

  useEffect(() => {
    onChange?.({ theme, scale, compact, fontFamily });
  }, [theme, scale, compact, fontFamily, onChange]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r)' }}>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}
      >
        <h2
          style={{
            fontFamily: 'var(--jx-font-display)',
            color: 'var(--jx-text)',
            margin: 0,
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent">{themeLabels[theme]}</JxBadge>
      </div>

      <JxToggle
        items={[
          { value: 'light', label: 'Светлая' },
          { value: 'dark', label: 'Тёмная' },
          { value: 'system', label: 'Системная' },
        ]}
        value={theme}
        onValueChange={(value) => setTheme(value as Theme)}
      />

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={5}
        unit="%"
        showOutput
        value={scale}
        onValueChange={setScale}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={compact}
        onChange={(event) => setCompact(event.target.checked)}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        options={[
          { value: 'sans', label: 'Inter Tight' },
          { value: 'display', label: 'Fraunces' },
          { value: 'mono', label: 'JetBrains Mono' },
        ]}
        value={fontFamily}
        onValueChange={setFontFamily}
      />
    </div>
  );
}

